CREATE TABLE IF NOT EXISTS `status` (`name` varchar(64) NOT NULL, `value` text) ENGINE=vdb_mysql_storage;
CREATE TABLE IF NOT EXISTS `tables` (`table_schema` varchar(64) NOT NULL, `table_name` varchar(64) NOT NULL, `kind` varchar(16), `delta_rows` bigint unsigned, `touched_keys` bigint unsigned, `delta_bytes` bigint unsigned, `unproven_collations` text, `last_source_change` datetime(6)) ENGINE=vdb_mysql_storage;
CREATE TABLE IF NOT EXISTS `sessions` (`connection_id` bigint unsigned NOT NULL, `account` varchar(300), `snapshot_age_ms` bigint, `source_requests` bigint, `source_rows` bigint, `statements_without_bka` bigint) ENGINE=vdb_mysql_storage;
CREATE TABLE IF NOT EXISTS `source_requests` (`connection_id` bigint unsigned, `digest` varchar(64), `shape` varchar(32), `table_schema` varchar(64), `table_name` varchar(64), `started` datetime(6), `duration_us` bigint, `rows` bigint, `bytes` bigint, `error` text) ENGINE=vdb_mysql_storage;
CREATE TABLE IF NOT EXISTS `accounts` (`user` varchar(255) NOT NULL, `host` varchar(255) NOT NULL, `method` varchar(64), `grants_read_at` datetime(6), `reachable` tinyint(1), `reason` text) ENGINE=vdb_mysql_storage;
CREATE TABLE IF NOT EXISTS `catalog_errors` (`object_type` varchar(16), `object_schema` varchar(64), `object_name` varchar(64), `error` text) ENGINE=vdb_mysql_storage;
CREATE TABLE IF NOT EXISTS `delta_sql` (`seq` bigint unsigned NOT NULL, `kind` varchar(8), `object_schema` varchar(64), `object_name` varchar(64), `statement` longtext) ENGINE=vdb_mysql_storage;
CREATE TABLE IF NOT EXISTS `schema_changes` (`seq` bigint unsigned NOT NULL, `applied_at` datetime(6), `table_schema` varchar(64), `table_name` varchar(64), `change` text, `delta_effect` text, `affected` json) ENGINE=vdb_mysql_storage;
CREATE TABLE IF NOT EXISTS `metrics` (`name` varchar(128) NOT NULL, `labels` varchar(255) NOT NULL, `value` double) ENGINE=vdb_mysql_storage;
